import { Component, inject, signal } from '@angular/core';
import { iProjects } from '../../interface/projects.interface';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { eDialogPanelClass } from '../../enum/eDialogPanelClass.enum';
import { DialogProjectsComponent } from '../dialog/dialog-projects/dialog-projects.component';

@Component({
  selector: 'app-projects',
  standalone: true,
  imports: [MatDialogModule],
  templateUrl: './projects.component.html',
  styleUrl: './projects.component.scss'
})
export class ProjectsComponent {
  #dialog = inject(MatDialog);

  public arrayProjects = signal<iProjects[]>([
    {
      src: 'assets/img/projects/lista_de_tarefas.jpg',
      alt: 'Projeto Lista de Tarefas',
      title: 'Lista de Tarefas',
      width: '200px',
      height: '101px',
      description: 'Essa é uma aplicação em Angular 17. </br>Com intuito de praticar comunicação entre componentes utilizando @Input e @Output',
      links: [
        {
          name: 'Conheça a aplicação',
          href: 'https://brunopandreu.github.io/lista-de-tarefas/',
        }
      ]
    },
  ])

  public openDialog(data: iProjects) {
    this.#dialog.open(DialogProjectsComponent, {
      data,
      panelClass: eDialogPanelClass.PROJECTS,
    })
  }
}
